"""Türkçe — başlangıç seviyesi (200 soru)."""

T = {
"prophets_251": ("İslam Peygamberi'nin adı nedir?", ["Muhammed ﷺ", "İbrahim", "Musa", "İsa"], "İslam'ın Peygamberi, Abdullah'ın oğlu Muhammed ﷺ'dir."),
"prophets_252": ("İsmail ve İshak hangi peygamberin oğullarıdır?", ["İbrahim", "Musa", "Nuh", "Davud"], "«İhtiyarlığıma rağmen bana İsmail'i ve İshak'ı bağışlayan Allah'a hamdolsun» (14:39)."),
"prophets_253": ("Allah hangi peygamberi kendi katına yükseltti?", ["İsa", "Yunus", "Eyyub", "İdris"], "«Bilakis Allah onu kendi katına yükseltti» (4:158)."),
"prophets_254": ("İsa peygamberin annesi kimdir?", ["Meryem", "Asiye", "Hacer", "Sare"], "Meryem; Kur'an'da ona koca bir sure ayrılmıştır."),
"prophets_255": ("Allah'ın yarattığı ilk insan kimdir?", ["Âdem", "Nuh", "İbrahim", "İdris"], "Âdem, Allah'ın kendisine bütün isimleri öğrettiği ilk insandır."),
"prophets_256": ("Ateş hangi peygamber için serinlik ve esenlik oldu?", ["İbrahim", "Musa", "Yusuf", "Süleyman"], "«Ey ateş, İbrahim'e karşı serin ve esenlik ol.»"),
"prophets_257": ("Hangi peygamberin asası yılana dönüştü?", ["Musa", "Harun", "Yahya", "Zekeriya"], "Allah Musa'ya sordu: «Sağ elindeki nedir?»"),
"prophets_258": ("Hangi peygamber rüyasında on bir yıldızın secde ettiğini gördü?", ["Yusuf", "Yakub", "İshak", "Davud"], "«Babacığım, ben rüyamda on bir yıldız, güneşi ve ayı gördüm.»"),
"prophets_259": ("Süleyman peygambere hangi kuş haber getirdi?", ["Hüdhüd", "Karga", "Şahin", "Güvercin"], "Hüdhüd dedi ki: «Sana Sebe'den kesin bir haber getirdim» (27:22)."),
"prophets_260": ("Hangi peygamber imtihanda sabrın örneğidir?", ["Eyyub", "Yunus", "Lut", "Şuayb"], "Eyyub Rabbine yalvardı ve sabırlı bulundu."),
"prophets_261": ("Allah Âdem'i neyden yarattı?", ["Topraktan", "Nurdan", "Ateşten", "Rüzgârdan"], "«Onu topraktan yarattı, sonra ona: Ol! dedi» (3:59)."),
"prophets_262": ("Allah hangi peygamberle doğrudan konuştu?", ["Musa", "Yusuf", "Yunus", "Salih"], "«Ve Allah Musa ile gerçekten konuştu.»"),
"prophets_263": ("Muhammed ﷺ'den sonra kaç peygamber gelir?", ["Hiç: o peygamberlerin sonuncusudur", "Bir", "Üç", "Yedi"], "Muhammed ﷺ peygamberlerin mührüdür: ondan sonra peygamber gelmez."),
"prophets_264": ("Hangi peygambere Allah'ın yakın dostu (halil) denir?", ["İbrahim", "Musa", "İsa", "Nuh"], "İbrahim, peygamberlerin babası ve Rahman'ın yakın dostudur."),
"prophets_265": ("Hangi peygamber Allah'ın izniyle doğuştan körü iyileştirirdi?", ["İsa", "Yahya", "Zekeriya", "İlyas"], "«Benim iznimle doğuştan körü ve alacalıyı iyileştiriyordun.»"),
"prophets_266": ("Dağlar hangi peygamberle birlikte Allah'ı tesbih ediyordu?", ["Davud", "Süleyman", "Eyyub", "Yunus"], "«Ey dağlar, onunla birlikte Allah'ı tesbih edin.»"),
"prophets_267": ("Mısır hükümdarının rüyasını hangi peygamber açıkladı?", ["Yusuf", "Harun", "İlyas", "Şuayb"], "Yusuf yedi semiz ve yedi zayıf ineğin anlamını açıkladı (12:46-49)."),
"prophets_268": ("Yusuf peygamberin babası kimdir?", ["Yakub", "İshak", "İbrahim", "Lut"], "Yusuf, İshak'ın oğlu olan Yakub'un oğludur."),
"prophets_269": ("Musa ve kavminin önünde ne yarıldı?", ["Onları Firavun'dan kurtarmak için deniz", "Mısır'ın bir nehri", "Medyen'de bir göl", "Bir çöl kuyusu"], "«Hani sizin için denizi yarmış ve sizi kurtarmıştık.»"),
"prophets_270": ("Peygamber ﷺ'in adı anıldığında ne söylenir?", ["«Allah'ın salât ve selamı onun üzerine olsun»", "Özel bir şey söylenmez", "«Teşekkür ederim»", "«Hoşça kal»"], "Ona salât ve selam getirilir: sallallahu aleyhi ve sellem."),
"prophets_271": ("Hangi peygamber tufandan önce kavmini çok uzun süre davet etti?", ["Nuh", "Hud", "Salih", "Şuayb"], "«Nuh'u kavmine gönderdik: kavmini uyar.»"),
"prophets_272": ("Süleyman hangi peygamberin oğludur?", ["Davud", "Yakub", "İshak", "Yunus"], "«Davud'a Süleyman'ı bağışladık; ne güzel bir kul!» (38:30)."),
"prophets_273": ("Hangi peygamber Câlût'u (Golyat) yendi?", ["Davud", "Süleyman", "Yuşa", "İlyas"], "«Davud Câlût'u öldürdü» (2:251)."),
"prophets_274": ("Bir Müslüman kaç peygambere inanmalıdır?", ["Hepsine, aralarında ayrım yapmadan", "Yalnızca sonuncusuna", "Yalnızca üçüne", "Yalnızca Kur'an'da adı geçenlere"], "Müslüman, Allah'ın bütün peygamberlerine aralarında ayrım yapmadan inanır."),
"prophets_275": ("Kur'an'a göre Allah kimleri seçti?", ["Âdem'i, Nuh'u, İbrahim ailesini ve İmran ailesini", "Mısır krallarını", "Medine kabilelerini", "Sebe halkını"], "«Allah Âdem'i, Nuh'u, İbrahim ailesini ve İmran ailesini seçti.»"),
"prophets_276": ("Yusuf peygamber hangi ülkede hükümdarın güvendiği kişi oldu?", ["Mısır", "Şam", "Yemen", "Irak"], "Yusuf, hükümdarın rüyasını yorumladıktan sonra Mısır'da yüksek bir konuma getirildi."),
"prophets_277": ("Hangi peygamber bir gece Mescid-i Aksa'ya götürüldü?", ["Muhammed ﷺ", "Musa", "İsa", "İbrahim"], "«Kulunu bir gece yürüten Allah her türlü noksandan uzaktır.»"),
"prophets_278": ("Musa peygambere hangi kitap verildi?", ["Tevrat", "İncil", "Zebur", "İbrahim'in sahifeleri"], "Allah Musa'ya Kitab'ı verdi ve ardından elçiler gönderdi."),
"prophets_279": ("İsa peygambere hangi kitap verildi?", ["İncil", "Tevrat", "Zebur", "Kur'an"], "«Ona içinde hidayet ve nur bulunan İncil'i verdik.»"),
"prophets_280": ("Davud peygambere hangi kitap verildi?", ["Zebur", "Tevrat", "İncil", "Musa'nın sahifeleri"], "«Davud'a da Zebur'u verdik.»"),
"prophets_281": ("Hangi peygamberin oğlu Allah'a itaat ederek kurban edilmeyi kabul etti?", ["İbrahim'in oğlu", "Nuh'un oğlu", "Musa'nın kardeşi", "Yakub'un oğlu"], "«Babacığım, sana emredileni yap: beni sabredenlerden bulacaksın.»"),
"prophets_282": ("Musa'nın annesi onu kurtarmak için bebeğini nereye bıraktı?", ["Nehre", "Bir mağaraya", "Bir komşuya", "Çöle"], "«Onu nehre bırak: biz onu sana geri döndüreceğiz.»"),
"prophets_283": ("Yunus karanlıklar içinde ne dedi? Her Müslüman bu sözü tekrar eder.", ["«Senden başka ilah yoktur, seni tesbih ederim, ben zalimlerden oldum»", "«Bana zenginlik ver»", "«Beni kral yap»", "«Beni güçlü kıl»"], "Yunus'un balığın karnındaki duası."),
"prophets_284": ("Peygamber Muhammed ﷺ'in babası kimdir?", ["Abdullah", "Ebu Talib", "Abbas", "Hamza"], "O, Abdülmuttalib'in oğlu Abdullah'ın oğlu Muhammed ﷺ'dir."),
"prophets_285": ("Peygamber Muhammed ﷺ'in annesi kimdir?", ["Âmine", "Hatice", "Aişe", "Fatıma"], "Âmine bint Vehb, Peygamber ﷺ'in annesidir."),
"prophets_286": ("İsa henüz beşikteyken ne dedi?", ["«Ben Allah'ın kuluyum»", "«Ben bir kralım»", "«Ben bir meleğim»", "Hiçbir şey demedi"], "«Şüphesiz ben Allah'ın kuluyum: O bana Kitab'ı verdi.»"),
"prophets_287": ("Âd kavmine hangi peygamber gönderildi?", ["Hud", "Salih", "Lut", "Şuayb"], "«Âd kavmine de kardeşleri Hud'u gönderdik.»"),
"prophets_288": ("Semud kavmine dişi deveyle hangi peygamber gönderildi?", ["Salih", "Hud", "Yunus", "İdris"], "«Semud'a da kardeşleri Salih'i gönderdik: işte bu, Allah'ın dişi devesidir.»"),
"prophets_289": ("Hangi peygamber Musa'nın kardeşidir ve onunla birlikte gönderildi?", ["Harun", "Yusuf", "Yahya", "İlyas"], "«Bana ailemden bir yardımcı ver: kardeşim Harun'u.»"),
"prophets_290": ("Kur'an, peygamberler arasında Muhammed ﷺ'e hangi unvanı verir?", ["Peygamberlerin mührü (sonuncusu)", "Peygamberlerin ilki", "Peygamberlerin kralı", "Peygamberlerin kâtibi"], "«Muhammed Allah'ın Resulü ve peygamberlerin sonuncusudur.»"),
"prophets_291": ("Kur'an'da melekler Meryem'e ne der?", ["Allah'ın onu seçip tertemiz kıldığını", "Kraliçe olacağını", "Yolculuğa çıkacağını", "Öğretmen olacağını"], "«Ey Meryem, Allah seni seçti ve tertemiz kıldı.»"),
"prophets_292": ("Eyyub imtihanında Rabbine nasıl yalvardı?", ["«Bana zarar dokundu, sen merhametlilerin en merhametlisisin»", "«Beni zengin et»", "«Düşmanlarımı cezalandır»", "«Beni kral yap»"], "«Bana zarar dokundu; sen merhametlilerin en merhametlisisin.»"),
"prophets_293": ("Allah Âdem'e ne öğretti?", ["Bütün isimleri", "Yazıyı", "Denizciliği", "Hesabı"], "«Ve Âdem'e bütün isimleri öğretti.»"),
"prophets_294": ("Hangi peygamber, kendisinden sonra kimseye nasip olmayacak bir hükümdarlığa sahipti?", ["Süleyman", "Davud", "Yusuf", "Zülkarneyn"], "«Bana, benden sonra kimseye nasip olmayacak bir hükümdarlık bağışla.»"),
"prophets_295": ("Hangi peygamber, karısı hariç ailesiyle birlikte kurtarıldı?", ["Lut", "Nuh", "Hud", "Salih"], "«Gecenin bir bölümünde ailenle yola çık… karın hariç.»"),
"prophets_296": ("İbrahim kavmini neye karşı uyardı?", ["Putlara tapmaya karşı", "Ticarete karşı", "Yolculuğa karşı", "Yazıya karşı"], "«Putları ilah mı ediniyorsun?»"),
"prophets_297": ("Allah'ın insanlara gönderdiği elçiyi hangi kelime ifade eder?", ["Resul (elçi)", "Halife", "Sahabi", "Âlim"], "Resul, Allah'ın gönderdiği ve insanlara bir mesaj iletmekle görevli elçidir."),
"prophets_298": ("Ahzab suresine göre Allah Peygamber ﷺ'i ne olarak gönderdi?", ["Şahit, müjdeci ve uyarıcı olarak", "Kral ve hâkim olarak", "Tüccar olarak", "Şair olarak"], "«Ey Peygamber, biz seni şahit, müjdeci ve uyarıcı olarak gönderdik» (33:45)."),
"prophets_299": ("Kur'an'a göre Muhammed ﷺ niçin gönderildi?", ["Âlemlere rahmet olarak", "Hükmetmek için", "İnşa etmek için", "Ticaret yapmak için"], "«Biz seni ancak âlemlere rahmet olarak gönderdik.»"),
"prophets_300": ("Kur'an hangi peygambere «çok şükreden bir kul» der?", ["Nuh", "Lut", "İdris", "İlyas"], "«Şüphesiz o, çok şükreden bir kuldu» (17:3): Nuh hakkında söylenir."),
"prophets_301": ("Oğlu müjdelendikten sonra Zekeriya'ya hangi işaret verildi?", ["Üç gün insanlarla konuşmaması", "Bir yıldız görmesi", "Gök gürültüsü duyması", "Su üstünde yürümesi"], "«Senin işaretin, üç gün insanlarla konuşmamandır» (3:41)."),
"prophets_302": ("Her elçi hangi dille gönderildi?", ["Kendi kavminin diliyle", "Yalnızca Arapça", "İbranice", "Gökten bir dille"], "«Biz her elçiyi ancak kendi kavminin diliyle gönderdik.»"),
"prophets_303": ("Hangi sure bir peygamberin kıssasını baştan sona anlatır?", ["Yusuf suresi", "Bakara suresi", "Nas suresi", "Fatiha suresi"], "«Biz sana kıssaların en güzelini anlatıyoruz»: Yusuf'un kıssası."),
"prophets_304": ("Kur'an, Meryem suresinde İbrahim'i nasıl niteler?", ["Dosdoğru bir kişi, bir peygamber", "Bir kral", "Bir kâtip", "Bir tüccar"], "«O, dosdoğru bir kişi ve bir peygamberdi.»"),
"prophets_305": ("Hangi kraliçe Süleyman peygamberi görmeye geldi?", ["Sebe melikesi", "Mısır kraliçesi", "Babil kraliçesi", "Kuzey Yemen kraliçesi"], "O, Süleyman ile birlikte âlemlerin Rabbi Allah'a teslim oldu."),
"prophets_306": ("Hangi peygamber Allah'ın ölüleri nasıl dirilttiğini görmek istedi?", ["İbrahim", "Musa", "Nuh", "Yunus"], "«Rabbim, ölüleri nasıl dirilttiğini bana göster.»"),
"prophets_307": ("Hangi peygamber ilim sahibi bir kuldan öğrenmek için yolculuk yaptı?", ["Musa", "Yusuf", "Davud", "Süleyman"], "Musa, Allah'ın kendisine ilim verdiği bir kuluyla karşılaşıncaya kadar yol aldı."),
"prophets_308": ("İhlas suresi Allah hakkında ne öğretir?", ["O'nun Bir olduğunu ve hiçbir şeyin O'na denk olmadığını", "Ortakları olduğunu", "Yarattıklarına benzediğini", "Bir oğlu olduğunu"], "«De ki: O Allah birdir… ve hiçbir şey O'na denk değildir.»"),
"prophets_309": ("Mekkeliler vahiyden önce Peygamber ﷺ'e ne derdi?", ["El-Emin, güvenilir", "Yolcu", "Şair", "Hâkim"], "Dürüstlüğü o kadar iyi biliniyordu ki ona el-Emin deniyordu."),
"prophets_310": ("Kur'an, izlenecek en güzel örnek olarak kimi sunar?", ["Allah'ın Resulü ﷺ'i", "Kralları", "Şairleri", "Tüccarları"], "«Andolsun ki Allah'ın Resulünde sizin için güzel bir örnek vardır.»"),
"sira_251": ("Peygamber ﷺ hangi şehirde doğdu?", ["Mekke", "Medine", "Kudüs", "Taif"], "Peygamber ﷺ Mekke'de, Kureyş kabilesinde doğdu."),
"sira_252": ("Peygamber ﷺ hangi şehre hicret etti?", ["Medine", "Taif", "Kahire", "Şam"], "Hicret Mekke'den, o zamanki adı Yesrib olan Medine'ye yapıldı."),
"sira_253": ("Mekke'den Medine'ye göçe ne denir?", ["Hicret", "Hac", "Fetih", "Antlaşma"], "Hicret, İslam takviminin başlangıcıdır."),
"sira_254": ("Peygamber ﷺ'in ilk eşi kimdir?", ["Hatice", "Aişe", "Hafsa", "Sevde"], "Hatice bint Huveylid, ona ilk inanan kişidir."),
"sira_255": ("Peygamber ﷺ hicret sırasında hangi mağarada saklandı?", ["Sevr mağarası", "Hira mağarası", "Uhud mağarası", "Kuba mağarası"], "Medine'ye yola çıkmadan önce orada Ebu Bekir ile üç gün saklandı."),
"sira_256": ("Peygamber ﷺ'e indirilen ilk kelime nedir?", ["«Oku»", "«Namaz kıl»", "«Kalk»", "«Dinle»"], "«Yaratan Rabbinin adıyla oku.»"),
"sira_257": ("Vahyi Peygamber ﷺ'e hangi melek getirdi?", ["Cebrail", "Mikail", "İsrafil", "Malik"], "Cebrail, vahyi indirmekle görevli melektir."),
"sira_258": ("Peygamber ﷺ'in kabri hangi şehirdedir?", ["Medine", "Mekke", "Kudüs", "Taif"], "Kabri Medine'de, mescidinin yanındadır."),
"sira_259": ("Peygamber ﷺ hangi kabiledendir?", ["Kureyş", "Evs", "Hazrec", "Sakif"], "Peygamber ﷺ, Mekke'nin kabilesi Kureyş'tendir."),
"sira_260": ("Peygamber ﷺ'in arkadaşlarına ne denir?", ["Sahabe", "Tâbiîn", "Yalnızca Ensar", "Kurrâ"], "Sahabe, Peygamber ﷺ'i ona inanmış olarak görenlerdir."),
"sira_261": ("Hicrette Peygamber ﷺ'e kim eşlik etti?", ["Ebu Bekir", "Ömer", "Osman", "Bilal"], "Ebu Bekir, hicret sırasında mağarada onun arkadaşıydı."),
"sira_262": ("Peygamber ﷺ'in müezzini kimdi?", ["Bilal", "Enes", "Zeyd", "Selman"], "Bilal bin Rebah Medine'de ezan okurdu."),
"sira_263": ("İslam'ın ilk savaşına ne denir?", ["Bedir", "Uhud", "Hayber", "Huneyn"], "Bedir, hicretin ikinci yılında yapılan ilk büyük savaştır."),
"sira_264": ("Mekke'den Medine'ye hicret edenlere ne denir?", ["Muhacirler", "Ensar", "Tâbiîn", "Taifli sahabiler"], "Muhacirler göç edenlerdir; Ensar ise onları karşılayanlardır."),
"sira_265": ("Muhacirleri karşılayan Medinelilere ne denir?", ["Ensar", "Muhacirler", "Kureyş", "Tâbiîn"], "Ensar, «yardımcılar», Medine'nin Evs ve Hazrec kabileleridir."),
"sira_266": ("Peygamber ﷺ Medine'de ilk olarak ne inşa etti?", ["Bir mescit", "Bir pazar", "Bir saray", "Bir sur"], "Medine'ye varır varmaz mescidini inşa etti."),
"sira_267": ("Peygamber ﷺ'in hangi kızı Ali ile evlendi?", ["Fatıma", "Rukiye", "Zeynep", "Ümmü Gülsüm"], "Peygamber ﷺ'in kızı Fatıma, Ali bin Ebu Talib ile evlendi."),
"sira_268": ("Peygamber ﷺ'den sonraki ilk halife kimdir?", ["Ebu Bekir", "Ömer", "Osman", "Ali"], "Ebu Bekir es-Sıddık ilk halifeydi."),
"sira_269": ("Medine'nin eski adı neydi?", ["Yesrib", "Bekke", "Taif", "Hayber"], "Yesrib, Medinetü'n-Nebi, yani Peygamber ﷺ'in şehri adını aldı."),
"sira_270": ("İlk vahiy geldiğinde Peygamber ﷺ kaç yaşındaydı?", ["Kırk yaşında", "Yirmi", "Altmış", "Otuz"], "Vahiy ona kırk yaşındayken geldi."),
"sira_271": ("Kâbe hangi şehirdedir?", ["Mekke", "Medine", "Kudüs", "Şam"], "Kâbe, Mekke'de Mescid-i Haram'ın ortasında yer alır."),
"sira_272": ("Mescid-i Aksa hangi şehirdedir?", ["Kudüs", "Mekke", "Medine", "Kahire"], "Mescid-i Aksa Kudüs'tedir (el-Kuds)."),
"sira_273": ("Peygamber ﷺ'in hangi amcası onu Mekke'de korudu?", ["Ebu Talib", "Ebu Leheb", "Abbas", "Ebu Süfyan"], "Ali'nin babası Ebu Talib, yeğenini Kureyş'e karşı korudu."),
"sira_274": ("Peygamber ﷺ'in ilk eşi Hatice'nin mesleği neydi?", ["Tüccar", "Hekim", "Şair", "Dokumacı"], "Hatice, Mekke'nin saygın bir tüccarıydı."),
"sira_275": ("Peygamber ﷺ'in son haccına ne denir?", ["Veda Haccı", "İlk hac", "Fetih haccı", "Küçük hac (umre)"], "Veda Haccı hicretin 10. yılında yapıldı."),
"sira_276": ("Peygamber ﷺ'in hayatının anlatımına ne denir?", ["Siyer", "Sünnet", "Tefsir", "Fıkıh"], "Siyer onun hayatının anlatımıdır; Sünnet ise söyledikleri ve yaptıklarıdır."),
"sira_277": ("Peygamber ﷺ'den rivayet edilen bir söze ne denir?", ["Hadis", "Sure", "Ayet", "Dua"], "Hadis, Peygamber ﷺ'in sözü, fiili veya onayıdır."),
"sira_278": ("En titiz sayılan iki hadis kitabı hangileridir?", ["Sahih-i Buhari ve Sahih-i Müslim", "İki şiir kitabı", "İki tarih kitabı", "İki sözlük"], "İkisine birlikte «Sahihayn» (iki Sahih) denir."),
"sira_279": ("Hangi halife Kur'an'ı çoğaltıp eyaletlere gönderdi?", ["Osman", "Ebu Bekir", "Ömer", "Ali"], "Osman resmî nüshalar hazırlatıp büyük şehirlere gönderdi."),
"sira_280": ("«Râşid halifeler» (doğru yolda giden halifeler) kaç kişidir?", ["Dört", "İki", "Yedi", "On iki"], "Ebu Bekir, Ömer, Osman ve Ali."),
"sira_281": ("Müslümanlar hangi yöne dönerek namaz kılar?", ["Mekke'deki Kâbe'ye doğru", "Kudüs'e doğru", "Doğuya doğru", "Medine'ye doğru"], "Kıble, Kâbe'nin yönüdür."),
"sira_282": ("Bu namaz yönüne ne denir?", ["Kıble", "Mihrap", "Minber", "Minare"], "Kıble yöndür; mihrap ise onu gösteren oyuktur."),
"sira_283": ("Müslümanların birlikte namaz kıldığı yere ne denir?", ["Mescit (cami)", "Okul", "Pazar", "Kütüphane"], "Mescit, secde edilen yer, yani camidir."),
"sira_284": ("Namaza çağrıya ne denir?", ["Ezan", "Tekbir", "Tesbih", "Zikir"], "Ezan çağrıdır; onu okuyana müezzin denir."),
"sira_285": ("Müslümanlar büyük namaz için hangi gün toplanır?", ["Cuma", "Cumartesi", "Pazar", "Pazartesi"], "Cuma namazı (el-cumua) her hafta cemaati bir araya getirir."),
"sira_286": ("Namazı kıldıran kişiye ne denir?", ["İmam", "Müezzin", "Kadı", "Hafız"], "İmam, cemaatin arkasında saf tutup namaz kıldığı kişidir."),
"sira_287": ("Kur'an'ın tamamını ezberleyen kişiye ne denir?", ["Hafız", "İmam", "Müezzin", "Kadı"], "Hafız, Kur'an'ın tamamını ezberinde tutan kişidir."),
"sira_288": ("Hangi sahabi en çok hadis rivayet eden kişi olarak bilinir?", ["Ebu Hureyre", "Bilal", "Selman", "Enes"], "Ebu Hureyre, Peygamber ﷺ'in son yıllarını onun yanında geçirdi."),
"sira_289": ("Hangi halifeye es-Sıddık, «doğrulayan» denir?", ["Ebu Bekir", "Ömer", "Osman", "Ali"], "Ebu Bekir es-Sıddık, iman eden ilk hür erkektir."),
"sira_290": ("Hangi halifeye el-Faruk denir?", ["Ömer bin Hattab", "Ebu Bekir", "Osman", "Ali"], "Hakkı batıldan ayıran Ömer'e bu unvan verildi."),
"sira_291": ("Hangi halife Kur'an'ı tek bir mushafta toplattı?", ["Ebu Bekir", "Muaviye", "Halid", "Bilal"], "Ebu Bekir, yazılı olanların bir araya toplanmasını emretti."),
"sira_292": ("Peygamber ﷺ'i çocukken hangi dedesi büyüttü?", ["Abdülmuttalib", "Ebu Süfyan", "Velid", "Utbe"], "Dedesi Abdülmuttalib, doğumundan sonra onu himayesine aldı."),
"sira_293": ("Kur'an, Peygamber ﷺ'in çocukluğunu nasıl hatırlatır?", ["Allah onu yetim bulup barındırdı", "O bir kraldı", "Çocukluğundan beri zengindi", "Çölde tek başına yaşadı"], "«O seni yetim bulup barındırmadı mı?» (93:6)."),
"sira_294": ("Bedir'den sonra hangi savaş geldi?", ["Uhud", "Hendek", "Huneyn", "Tebük"], "Ertesi yıl Medine yakınında Uhud Savaşı yapıldı."),
"sira_295": ("Müslümanlar Medine'yi savunmak için çevresine ne kazdı?", ["Bir hendek (el-Handek)", "Bir kuyu", "Bir tünel", "Bir kanal"], "Bir hendek kazdılar; Hendek Savaşı adını buradan alır."),
"sira_296": ("Peygamber ﷺ'in eşi Aişe kimin kızıydı?", ["Ebu Bekir'in", "Ömer'in", "Osman'ın", "Ali'nin"], "Aişe, Ebu Bekir es-Sıddık'ın kızıydı."),
"sira_297": ("Kur'an, Peygamber ﷺ'in eşlerini nasıl adlandırır?", ["Müminlerin anneleri", "Hizmetçiler", "Yol arkadaşları", "Muhacir kadınlar"], "«Onun eşleri de müminlerin anneleridir» (33:6)."),
"sira_298": ("Hangi sahabi Peygamber ﷺ'in hem amcasının oğlu hem damadıydı?", ["Ali bin Ebu Talib", "Bilal", "Selman", "Zeyd"], "Peygamber ﷺ'in amcasının oğlu Ali, onun kızı Fatıma ile evlendi."),
"sira_299": ("Peygamber ﷺ'in Medine'deki mescidine ne denir?", ["Mescid-i Nebevi", "Mescid-i Haram", "Mescid-i Aksa", "Kuba"], "Peygamber Mescidi, Mescid-i Nebevi, Medine'dedir."),
"sira_300": ("Peygamber ﷺ'in gece yolculuğundaki bineğine ne denir?", ["Burak", "Adbâ", "Şakrâ", "Kasvâ"], "Gece yolculuğunun bineğine Burak denir."),
"faith_151": ("İslam'ın kaç şartı vardır?", ["Beş", "Üç", "Altı", "On"], "Beş: kelime-i şehadet, namaz, zekât, oruç ve hac."),
"faith_152": ("İslam'ın ilk şartı nedir?", ["Kelime-i şehadet", "Oruç", "Hac", "Zekât"], "İslam'a, Allah'tan başka ilah olmadığına ve Muhammed ﷺ'in O'nun elçisi olduğuna şahitlik ederek girilir."),
"faith_153": ("Bir Müslüman günde kaç farz namaz kılar?", ["Beş", "Üç", "Yedi", "İki"], "Sabahtan geceye yayılmış beş vakit namaz."),
"faith_154": ("Müslümanlar hangi ayda oruç tutar?", ["Ramazan", "Recep", "Şaban", "Şevval"], "«Ramazan ayı, Kur'an'ın indirildiği aydır» (2:185)."),
"faith_155": ("İslam'ın farz olan sadakasına ne denir?", ["Zekât", "Dua", "Zikir", "Tavaf"], "Zekât, malın her yıl verilen payıdır."),
"faith_156": ("Mekke'ye yapılan büyük ziyarete ne denir?", ["Hac", "Sa'y", "Zikir", "Sahur"], "Hac, gücü yetenlerin ömürde bir kez yaptığı ziyarettir."),
"faith_157": ("İmanın kaç esası (erkân-ı iman) vardır?", ["Altı", "Dört", "Beş", "Yedi"], "Allah'a, meleklerine, kitaplarına, peygamberlerine, ahiret gününe ve kadere inanmak."),
"faith_158": ("Bir Müslüman kaç ilaha inanır?", ["Yalnızca bir", "İki", "Üç", "Birçok"], "«De ki: O Allah birdir» (112:1)."),
"faith_159": ("Müslümanlar Arapçada Tanrı'ya ne der?", ["Allah", "Melek", "Resul", "Nebi"], "Allah, Yaratıcı'nın Arapçadaki adıdır."),
"faith_160": ("Müslümanların kutsal kitabına ne denir?", ["Kur'an", "Tevrat", "İncil", "Zebur"], "Kur'an, Peygamber Muhammed ﷺ'e indirilen kitaptır."),
"faith_161": ("Mekke'de inşa edilen Allah'ın Evi'ne ne denir?", ["Kâbe", "Ravza", "Makam", "Hicr"], "«İnsanlar için kurulan ilk ev, Bekke'dekidir» (3:96)."),
"faith_162": ("Bir Müslüman yemeğe başlamadan önce ne der?", ["Bismillah", "Âmin", "Sübhanallah", "Allahümme"], "Peygamber ﷺ bir çocuğa öğretti: «Bismillah de ve sağ elinle ye.»"),
"faith_163": ("Müslümanlar birbirlerini nasıl selamlar?", ["Es-selâmü aleyküm", "Elhamdülillah", "Bismillah", "Allahu ekber"], "«Es-selâmü aleyküm» şu demektir: selam üzerinize olsun."),
"faith_164": ("«Es-selâmü aleyküm»e ne cevap verilir?", ["Ve aleykümü's-selâm", "Bismillah", "Âmin", "Sübhanallah"], "Selam iade edilir: «selam sizin de üzerinize olsun»."),
"faith_165": ("Ramazan ayının hemen ardından gelen bayrama ne denir?", ["Ramazan Bayramı (İd-i Fıtr)", "Kurban Bayramı (İd-i Adha)", "Kadir Gecesi", "Aşure"], "Ramazan Bayramı, orucun bitişinin bayramıdır."),
"faith_166": ("Kurban kesilen bayrama ne denir?", ["Kurban Bayramı (İd-i Adha)", "Ramazan Bayramı (İd-i Fıtr)", "Mevlid", "Kadir Gecesi"], "Kurban Bayramı hac günlerinde kutlanır."),
"faith_167": ("Allah'a her zaman itaat eden ve asla isyan etmeyen yaratıklara ne denir?", ["Melekler", "Cinler", "Peygamberler", "Sahabiler"], "Melekler, Allah'ın emrettiğini yerine getirir ve asla isyan etmezler."),
"faith_168": ("Arapçada cennete ne denir?", ["El-Cenne", "Es-Salât", "Ed-Dua", "El-Ezan"], "Kelime anlamı «bahçe» olan el-Cenne, müminlere vadedilen yurttur."),
"faith_169": ("Namazdan önce suyla yapılan temizliğe ne denir?", ["Abdest (vudû)", "Tavaf", "Zikir", "Sa'y"], "Abdest, namazdan önce yapılan temizliktir."),
"faith_170": ("Namazın bir birimine ne denir?", ["Rekât", "Sure", "Ezan", "Tavaf"], "Bir rekât, kıyamı (ayakta durmayı), rükûyu ve secdeleri içerir."),
"faith_171": ("Namazın her rekâtında hangi sure okunur?", ["Fatiha", "İhlas", "Nas", "Kevser"], "Açılış suresi Fatiha her rekâtta okunur."),
"faith_172": ("İslam'da izin verilen şeye ne denir?", ["Helal", "Haram", "Sünnet", "Farz"], "Helal, meşru olan demektir."),
"faith_173": ("İslam'da yasak olan şeye ne denir?", ["Haram", "Helal", "Mübah", "Nafile"], "Haram, yasak olan demektir."),
"faith_174": ("Kur'an hangi eti yasaklar?", ["Domuz eti", "Kuzu eti", "Sığır eti", "Tavuk eti"], "«O size ölü hayvanı, kanı ve domuz etini haram kıldı» (2:173)."),
"faith_175": ("Kur'an hangi içecekten uzak durmayı emreder?", ["Şarap ve her türlü sarhoş edici", "Süt", "Bal", "Yağmur suyu"], "«Şarap, kumar… birer pisliktir; onlardan uzak durun» (5:90)."),
"faith_176": ("Peygamber ﷺ'in öğrettiğine göre hapşıran kişi ne der?", ["Elhamdülillah", "Bismillah", "Allahu ekber", "Âmin"], "«Biriniz hapşırdığında elhamdülillah desin.»"),
"faith_177": ("Arapçada «namaz» nasıl söylenir?", ["Es-salât", "Es-savm", "Ez-zekât", "El-hac"], "Es-salât, Müslümanın kıldığı namazdır."),
"faith_178": ("Allah'tan kendi sözlerinle bir şey istemeye ne denir?", ["Dua", "Tavaf", "Ezan", "Sa'y"], "Dua, Allah'a yalvarmak, O'na seslenmektir."),
"faith_179": ("«Elhamdülillah» ne demektir?", ["Hamd Allah'a mahsustur", "Allah en büyüktür", "Allah'ın adıyla", "Allah her türlü noksandan uzaktır"], "Fatiha'nın ikinci ayetidir: «Hamd, âlemlerin Rabbi Allah'a mahsustur» (1:2)."),
"faith_180": ("«İslam» kelimesi ne demektir?", ["Allah'a teslim olmak", "Zenginlik", "Yolculuk", "Bilgi"], "İslam, teslim olmak ve barış içinde olmak anlamına gelen bir kökten gelir."),
"faith_181": ("«Müslüman» kelimesi ne demektir?", ["Allah'a teslim olan", "Yolculuk eden", "Öğreten", "İnşa eden"], "Müslüman, yalnızca Allah'a teslim olan kişidir."),
"faith_182": ("Kur'an'a göre gökleri ve yeri kim yarattı?", ["Allah", "Melekler", "Peygamberler", "Güneş"], "«Hamd, gökleri ve yeri yaratan Allah'a mahsustur» (6:1)."),
"faith_183": ("Hadis Allah'ın kaç ismini anar?", ["Doksan dokuz", "On", "Elli", "Bin"], "«Allah'ın doksan dokuz ismi vardır, yüzden bir eksik.»"),
"faith_184": ("«Değerli yazıcılar» denilen melekler ne yapar?", ["Amellerimizi yazarlar", "Yağmuru taşırlar", "Kâbe'yi korurlar", "Arapça öğretirler"], "«Değerli yazıcılar, yaptıklarınızı bilirler» (82:11-12)."),
"faith_185": ("Kur'an hangi geceyi bin aydan hayırlı diye niteler?", ["Kadir Gecesi", "Cuma gecesi", "Bayram gecesi", "Ramazan'ın ilk gecesi"], "«Kadir Gecesi bin aydan hayırlıdır» (97:3)."),
"faith_186": ("Tek bir Allah'a inanmaya ne denir?", ["Tevhid", "Tavaf", "Teyemmüm", "Teravih"], "Tevhid, Allah'ın birliğidir; bütün peygamberlerin mesajının özüdür."),
"faith_187": ("İbadette Allah'a ortak koşmaya ne denir?", ["Şirk", "Zikir", "Dua", "Sabır"], "Şirk ortak koşmaktır: Allah'ın yanında başka bir şeye tapmak."),
"faith_188": ("Herkesin hesaba çekileceği güne ne denir?", ["Kıyamet Günü", "Bayram günü", "Cuma", "Ramazan'ın ilk günü"], "Yevmü'l-Kıyame, Kıyamet Günü: herkesin amellerini göreceği gün."),
"faith_189": ("Kur'an'a göre yılda kaç ay vardır?", ["On iki", "On", "On dört", "Altı"], "«Allah katında ayların sayısı on ikidir» (9:36)."),
"faith_190": ("Bir rekâtta kaç secde vardır?", ["İki", "Bir", "Üç", "Dört"], "Her rekâtta iki secde vardır."),
"quran_151": ("Kur'an kaç sureden oluşur?", ["Yüz on dört", "Altmış", "İki yüz", "Otuz"], "Kur'an, Fatiha'dan Nas'a kadar 114 sureden oluşur."),
"quran_152": ("Kur'an'ın ilk suresi hangisidir?", ["Fatiha", "Bakara", "Nas", "Yasin"], "Fatiha, «açılış», ilk suredir."),
"quran_153": ("«Kur'an» kelimesi ne demektir?", ["Okuma, tilavet", "Yol", "Nur", "Bahçe"], "Kur'an, okumak ve tilavet etmek anlamına gelen bir kökten gelir."),
"quran_154": ("Kur'an yaklaşık kaç yılda indirildi?", ["Yaklaşık yirmi üç yılda", "Tek bir gecede", "Yüz yılda", "Üç yılda"], "Vahiy yaklaşık yirmi üç yıla yayıldı."),
"quran_155": ("Kur'an'ın numaralanmış her cümlesine ne denir?", ["Ayet", "Sure", "Cüz", "Hadis"], "Kur'an'ın numaralanmış her cümlesi bir ayettir, yani bir «işaret»."),
"quran_156": ("Kur'an'ın bir bölümüne ne denir?", ["Sure", "Ayet", "Cüz", "Hutbe"], "Kur'an, her birinin kendi adı olan surelere ayrılır."),
"quran_157": ("Kur'an'ın en uzun suresi hangisidir?", ["Bakara", "Fatiha", "Kevser", "Nas"], "Bakara, Kur'an'ın en uzun suresidir."),
"quran_158": ("Kur'an'ın en kısa suresi hangisidir?", ["Kevser", "Bakara", "Âl-i İmran", "Nisa"], "Kevser yalnızca üç ayettir."),
"quran_159": ("Hemen hemen her sure hangi cümleyle başlar?", ["Rahman ve Rahim olan Allah'ın adıyla", "Hamd Allah'a mahsustur", "Allah en büyüktür", "Allah'tan başka ilah yoktur"], "Besmele, 114 surenin 113'ünü açar."),
"quran_160": ("Kur'an kimin sözüdür?", ["Allah'ın", "Peygamber ﷺ'in", "Melek Cebrail'in", "Sahabilerin"], "Kur'an, 9:6'da kendisini «Allah'ın kelamı» (kelâmullah) diye adlandırır."),
"quran_161": ("Kur'an kaç bölüme (cüze) ayrılır?", ["Otuz", "On", "Elli", "Yüz"], "Kur'an, Ramazan'ın her gecesi için bir tane olmak üzere otuz cüze ayrılır."),
"quran_162": ("Hangi sure bir kadının adını taşır?", ["Meryem", "Yusuf", "Nuh", "Muhammed"], "19. sure Meryem'in adını taşır."),
"quran_163": ("Sığınmak için okunan son iki sureye ne denir?", ["Muavvizeteyn", "Mesânî", "Mufassal", "Havâmîm"], "Felak ve Nas'a Muavvizeteyn, «iki koruyucu» denir."),
"quran_164": ("Fatiha suresi besmeleden sonra hangi kelimeyle başlar?", ["El-hamdü", "Kul", "İkra", "İnnâ"], "«El-hamdü lillâhi rabbi'l-âlemîn» Fatiha'yı açar."),
"quran_165": ("Kur'an'ın anlamının açıklanmasına ne denir?", ["Tefsir", "Tecvid", "Hıfz", "Tavaf"], "Tefsir, ayetlerin anlamını açıklayan ilimdir."),
"quran_166": ("Hangi sure besmeleyle başlamaz?", ["Tevbe", "Fatiha", "İhlas", "Nasr"], "Tevbe, besmeleyle başlamayan tek suredir."),
"quran_167": ("Kur'an'ı sesli okuyan kişiye ne denir?", ["Kâri", "Müezzin", "İmam", "Hatip"], "Kâri, Kur'an okuyucusudur."),
"quran_168": ("Âyetü'l-Kürsî hangi surededir?", ["Bakara", "Kehf", "Yasin", "Mülk"], "Âyetü'l-Kürsî, Bakara suresinin 255. ayetidir."),
"quran_169": ("24. surenin adı «Nur» ne demektir?", ["Işık", "Gece", "Rüzgâr", "Dağ"], "Nur, «ışık» demektir."),
"quran_170": ("Hangi sure «Rahmeti bol olan» adını taşır?", ["Rahman", "Mülk", "Fetih", "Saff"], "55. sureye Rahman denir."),
"quran_171": ("Hangi sure mağaranın adını taşır?", ["Kehf", "Fil", "Neml", "Bakara"], "Kehf, «mağara» demektir."),
"quran_172": ("4. surenin adı «Nisa» ne demektir?", ["Kadınlar", "Erkekler", "Çocuklar", "Yolcular"], "Nisa, «kadınlar» demektir."),
"quran_173": ("5. surenin adı «Maide» ne demektir?", ["Sofra", "Dağ", "Demir", "Şafak"], "Maide, «sofra» demektir."),
"quran_174": ("71. sure hangi peygamberin adını taşır?", ["Nuh", "Hud", "Yunus", "İbrahim"], "71. sureye Nuh denir."),
"quran_175": ("Fatiha suresi kaç ayettir?", ["Yedi", "Üç", "On", "Yirmi"], "Fatiha yedi ayettir."),
"quran_176": ("Kur'an nerede korunduğunu söyler?", ["Levh-i Mahfuz'da (korunmuş bir levhada)", "Bir mağarada", "Bir sandıkta", "Bir dağda"], "«O, Levh-i Mahfuz'da bulunan şerefli bir Kur'an'dır» (85:21-22)."),
"quran_177": ("Hangi sure ayın adını taşır?", ["Kamer", "Şems", "Necm", "Leyl"], "Kamer, «ay» demektir."),
"quran_178": ("Hangi sure Kıyamet Günü'nün adını taşır?", ["Kıyame", "Fetih", "Haşr", "Saff"], "75. sureye Kıyame denir."),
"quran_179": ("14. sure hangi peygamberin adını taşır?", ["İbrahim", "Muhammed ﷺ", "Yusuf", "Hud"], "14. sureye İbrahim denir."),
"quran_180": ("57. surenin adı «Hadid» ne demektir?", ["Demir", "Altın", "Tahta", "Taş"], "Hadid, «demir» demektir."),
"virtues_101": ("Kur'an anne babamızla nasıl konuşmamızı söyler?", ["Saygılı sözlerle, «öf» bile demeden", "Onlardan daha yüksek sesle", "Hep susarak", "Yalnızca cuma günleri"], "«Onlara öf bile deme ve onlara güzel söz söyle» (17:23)."),
"virtues_102": ("Gönülden, iyilik olsun diye verilen bağışa ne denir?", ["Sadaka", "Zekât", "Tavaf", "Ezan"], "Sadaka, küçük veya büyük gönüllü bağıştır."),
"virtues_103": ("Peygamber ﷺ, Allah'a ve ahiret gününe inanan kişiye konuşma konusunda ne öğütler?", ["Ya hayır söylesin ya sussun", "Çok konuşsun", "Hiç konuşmasın", "Yalnızca ailesiyle konuşsun"], "«Allah'a ve ahiret gününe inanan ya hayır söylesin ya sussun.»"),
"virtues_104": ("Peygamber ﷺ komşumuza nasıl davranmamızı söyledi?", ["Ona ikramda bulunmayı", "Ondan kaçınmayı", "Onunla hiç konuşmamayı", "Ondan gitmesini istemeyi"], "«Allah'a ve ahiret gününe inanan komşusuna ikram etsin.»"),
"virtues_105": ("Kur'an'a göre Allah kimlerle beraberdir?", ["Sabredenlerle", "En zenginlerle", "En güçlülerle", "En hızlılarla"], "«Şüphesiz Allah sabredenlerle beraberdir» (2:153)."),
"virtues_106": ("Kur'an yetime ne yapmayı yasaklar?", ["Onu hor görmeyi", "Ona okumayı öğretmeyi", "Onu yemeğe davet etmeyi", "Onunla oynamayı"], "«Yetime gelince, onu hor görme» (93:9)."),
"virtues_107": ("Kur'an hangi sözden kaçınmamızı söyler?", ["Yalan sözden", "Yumuşak sözden", "Teşekkür sözünden", "Selam sözünden"], "«Yalan sözden kaçının» (22:30)."),
"virtues_108": ("Kur'an, yakın akrabayla birlikte kimlere hakkını vermemizi söyler?", ["Yoksula ve yolcuya", "Krala ve hâkime", "Tüccara", "Şaire"], "«Akrabaya, yoksula ve yolcuya hakkını ver» (17:26)."),
"virtues_109": ("Allah kendisine şükredene ne vadeder?", ["Ona daha fazlasını vermeyi", "Onu yolculuğa çıkarmayı", "Onu ünlü yapmayı", "Onu kral yapmayı"], "«Eğer şükrederseniz size elbette daha fazlasını veririm» (14:7)."),
"virtues_110": ("Arapçada «sabır» nasıl söylenir?", ["Es-sabr", "Eş-şükr", "Es-sıdk", "El-hayâ"], "Es-sabr, zorlukta ve itaatte direnç göstermektir."),
"faith_191": ("Allah'ı anmaya, O'nun övgüsünü tekrarlamaya ne denir?", ["Zikir", "Hac", "Sa'y", "Teyemmüm"], "Zikir, Allah'ı dille ve kalple anmaktır."),
"faith_192": ("Hicri yılın ilk ayı hangisidir?", ["Muharrem", "Ramazan", "Şevval", "Recep"], "Hicri yıl Muharrem ayıyla başlar."),
"faith_193": ("Bir günahtan sonra Allah'a dönmeye ne denir?", ["Tövbe", "Tavaf", "Tecvid", "Teravih"], "Tövbe pişmanlıktır: pişman olmak, vazgeçmek ve Allah'a dönmek."),
"faith_194": ("Yeryüzündeki her canlının rızkını kim verir?", ["Allah", "Krallar", "Tüccarlar", "Melekler"], "«Yeryüzünde hiçbir canlı yoktur ki rızkı Allah'a ait olmasın» (11:6)."),
"faith_195": ("Hac hangi şehirde yapılır?", ["Mekke'de", "Medine'de", "Kudüs'te", "Kahire'de"], "Hac, Mekke'de ve kutsal mekânlarında yapılır."),
"faith_196": ("Hac yapan kişiye ne denir?", ["Hacı", "İmam", "Kâri", "Müezzin"], "Hac yapana hacı denir."),
"faith_197": ("Kur'an'a göre Allah, gizlense bile neyi bilir?", ["Kalplerde olanı", "Yalnızca görünen amelleri", "Yalnızca söylenen sözleri", "Gizli hiçbir şeyi"], "«Göğüslerinizdekini gizleseniz de açığa vursanız da Allah onu bilir» (3:29)."),
"faith_198": ("Kur'an'a göre oruç kimlere farz kılındı?", ["Öncekilere olduğu gibi müminlere", "Yalnızca yolculara", "Yalnızca âlimlere", "Yalnızca çocuklara"], "«Ey iman edenler, sizden öncekilere farz kılındığı gibi oruç size de farz kılındı» (2:183)."),
"faith_199": ("Cuma günü cemaatle kılınan büyük namaza ne denir?", ["Cuma namazı (salâtü'l-cumua)", "Bayram namazı", "Vitir namazı", "Kuşluk (duha) namazı"], "Cuma namazı, Müslümanları cuma günü öğle vakti bir araya getirir."),
"faith_200": ("Arapçada «oruç» nasıl söylenir?", ["Es-savm", "Es-salât", "Ez-zekât", "El-ezan"], "Es-savm oruçtur, İslam'ın dördüncü şartıdır."),
}
